:root,
html,
body,
body.dark,
body[data-agy-theme] {
  /* 暗夜玄武岩与黑曜石底色 */
  --gothic-abyss: #050508 !important;
  --gothic-basalt: #08080D !important;
  --gothic-stone-card: #111018 !important;

  /* 吸血鬼血珀与古董鎏金 */
  --vampire-crimson: #9B0014 !important;
  --vampire-crimson-bright: #D90429 !important;
  --vampire-crimson-glow: rgba(217, 4, 41, 0.55) !important;
  --vampire-blood-deep: #4A000A !important;
  --vampire-gold: #D4AF37 !important;
  --vampire-gold-bright: #F3C643 !important;
  --vampire-gold-border: rgba(212, 175, 55, 0.5) !important;
  --vampire-gold-glow: rgba(243, 198, 67, 0.4) !important;

  /* 古老手抄本羊皮纸色阶 */
  --gothic-parchment: #EFE7D8 !important;
  --gothic-parchment-bright: #FFF9EE !important;
  --gothic-parchment-muted: #AFA492 !important;

  --font-gothic-title: 'Cinzel Decorative', 'Cinzel', 'MedievalSharp', serif !important;
  --font-gothic-body: 'Aa德古拉', 'Aa德古拉简', 'AaDracula', 'AaDeGuLaJian-2', 'AaDeGuLaJian', 'EB Garamond', 'Songti SC', 'Source Han Serif SC', serif !important;
  --font-gothic-mono: 'JetBrains Mono', 'Fira Code', monospace !important;

  --background: var(--gothic-basalt) !important;
  --content: var(--gothic-basalt) !important;
  --sidebar: var(--gothic-abyss) !important;
  --foreground: var(--gothic-parchment) !important;
  --primary: var(--vampire-crimson) !important;
  --border: rgba(212, 175, 55, 0.28) !important;
  --card: var(--gothic-stone-card) !important;
}

/* ----------------------------------------------------------------------------
 * 1. 《Pocket Mirror》游戏原生心形菱格暗纹背景 (Window_Pattern_Colored)
 *    提取自游戏官方系统素材 Window_Pattern_Colored.png
 *    - 核心周期修正：游戏原图 96x96 为 1.5 个周期，传统平铺会导致接缝处 4 颗心连结聚团；
 *      现已严格按 64x64 原生正交周期重构无缝真瓦片，彻底实现等距交错象棋格排列。
 *    - 舒展放大：已放大至 216px，画面呼吸感极佳，长时间注视柔和不眼晕。
 * ---------------------------------------------------------------------------- */
:root, html, body, body.dark, body[data-agy-theme] {
  --pm-pattern-size: 216px;
}

body,
body[data-agy-theme],
body[data-agy-font],
.theme-standalone,
.agy-shell,
.agy-inset-shell,
.agy-sheet,
div:has(> .agy-home),
.agy-inset-shell > div > div:nth-child(3),
.agy-inset-shell > div > div:nth-child(3) > div,
.agy-inset-shell > div > div:nth-child(3) .flex-1.min-h-0.flex.flex-col {
  background-color: #18050e !important;
  background-image: 
    radial-gradient(ellipse at 50% 40%, rgba(26, 6, 16, 0.2) 0%, rgba(8, 2, 5, 0.75) 100%),
    url("data:image/webp;base64,") !important;
  background-repeat: no-repeat, repeat !important;
  background-size: 100% 100%, var(--pm-pattern-size, 216px) var(--pm-pattern-size, 216px) !important;
  background-position: center center, 0 0 !important;
  background-attachment: fixed, fixed !important;
  color: var(--gothic-parchment) !important;
  font-family: var(--font-gothic-body) !important;
}

.agy-home {
  background-color: transparent !important;
  background-image: none !important;
}
/* ----------------------------------------------------------------------------
 * 2. 侧边栏：地下回廊与维多利亚蕾丝底色
 * ---------------------------------------------------------------------------- */
.bg-sidebar {
  background-color: #0d090a !important;
  background-image: url("data:image/webp;base64,") !important;
  background-attachment: fixed !important;
  background-position: left top !important;
  background-size: cover !important;
  background-repeat: no-repeat !important;
  border-right: 2px solid var(--vampire-gold-border) !important;
  box-shadow: inset -3px 0 24px rgba(0, 0, 0, 0.85) !important;
}

/* ----------------------------------------------------------------------------
 * 2.1 《Pocket Mirror》会话记录栏 SL_Box 镜像定制卡槽 UI (V2 黄金典藏版)
 *     - 结构优化：彻底剔除普通卡槽底图中的冗余玫瑰，实现纯净对称居中排版
 *     - 垂直居中：重置内部 flex 与行高，彻底消除文字偏向顶部与溢出UI问题
 *     - 专属法器：唯有激活选中的会话才具有顶部绯红金玫瑰与右侧上下浮动尖尖光标
 * ---------------------------------------------------------------------------- */

/* 2.1.1 通用基础尺寸与弹性居中排版（解决文本偏离、超出UI问题） */
:is([data-testid="conversation-row-sidebar"], .agy-sidebar-row):not(button[data-testid="project-header"]):not(button[data-project-card="true"]):not([data-project-label]) {
  position: relative !important;
  background-color: transparent !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-size: 100% 100% !important;
  border: none !important;
  box-shadow: none !important;
  --row-bg: transparent !important;
  min-height: 52px !important;
  height: 52px !important;
  margin: 4px 6px !important;
  padding-left: 20px !important;
  padding-right: 56px !important; /* 为右侧哥特十字与浮动光标留出从容空间 */
  box-sizing: border-box !important;
  display: flex !important;
  align-items: center !important;
  justify-content: flex-start !important;
  overflow: visible !important;
  transform-origin: center center !important;
  transition: transform 0.25s cubic-bezier(0.2, 0.8, 0.2, 1), opacity 0.25s ease, filter 0.25s ease !important;
}

/* 内部文字与链接容器垂直完全居中对齐，绝不向上偏离 */
:is([data-testid="conversation-row-sidebar"], .agy-sidebar-row):not(button[data-testid="project-header"]):not(button[data-project-card="true"]):not([data-project-label]) :is(a, [role="link"], div:has(> [class*="truncate"])) {
  display: flex !important;
  align-items: center !important;
  height: 100% !important;
  width: 100% !important;
  padding-top: 0 !important;
  padding-bottom: 0 !important;
  margin-top: 0 !important;
  margin-bottom: 0 !important;
}

:is([data-testid="conversation-row-sidebar"], .agy-sidebar-row):not(button[data-testid="project-header"]):not(button[data-project-card="true"]):not([data-project-label]) :is(span, [class*="truncate"]) {
  line-height: 1.25 !important;
  display: inline-flex !important;
  align-items: center !important;
  margin-top: 0 !important;
  margin-bottom: 0 !important;
  font-family: 'Lora', 'Source Han Serif SC', serif !important;
}

/* 2.1.2 未选中的普通会话记录卡槽：使用纯净对称 SL_Box_Slot，绝无玫瑰花 */
:is([data-testid="conversation-row-sidebar"], .agy-sidebar-row):not([data-selected="true"]):not([data-active="true"]):not([aria-selected="true"]):not(button[data-testid="project-header"]):not(button[data-project-card="true"]):not([data-project-label]) {
  background-image: url("data:image/webp;base64,") !important;
  transform: scale(0.96) !important;
  opacity: 0.68 !important;
  filter: brightness(0.8) grayscale(0.1) !important;
}

:is([data-testid="conversation-row-sidebar"], .agy-sidebar-row):not([data-selected="true"]):not([data-active="true"]):not([aria-selected="true"]):not(button[data-testid="project-header"]):not(button[data-project-card="true"]):not([data-project-label]) :is(span, [class*="truncate"]) {
  color: #cfbfaf !important;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.85) !important;
}

/* 2.1.3 鼠标悬停未选中会话记录卡槽：平滑唤醒微高光 */
:is([data-testid="conversation-row-sidebar"], .agy-sidebar-row):not([data-selected="true"]):not([data-active="true"]):not([aria-selected="true"]):not(button[data-testid="project-header"]):not(button[data-project-card="true"]):not([data-project-label]):hover {
  opacity: 0.92 !important;
  transform: scale(0.99) !important;
  filter: brightness(0.95) drop-shadow(0 2px 8px rgba(0, 0, 0, 0.6)) !important;
}

/* 2.1.4 当前选中的会话记录卡槽：高亮放大、金芒光晕、完全不透明 */
:is([data-testid="conversation-row-sidebar"], .agy-sidebar-row):is([data-selected="true"], [data-active="true"], [aria-selected="true"]):not(button[data-testid="project-header"]):not(button[data-project-card="true"]):not([data-project-label]) {
  background-image: url("data:image/webp;base64,") !important;
  min-height: 56px !important;
  height: 56px !important;
  transform: scale(1.04) !important;
  opacity: 1 !important;
  filter: brightness(1.15) drop-shadow(0 4px 14px rgba(0, 0, 0, 0.85)) drop-shadow(0 0 10px rgba(223, 186, 82, 0.45)) !important;
  z-index: 20 !important;
}

/* 选中会话文字高光与衬线字体 */
:is([data-testid="conversation-row-sidebar"], .agy-sidebar-row):is([data-selected="true"], [data-active="true"], [aria-selected="true"]) :is(span, [class*="truncate"]) {
  color: #ffe38f !important;
  font-weight: 600 !important;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.95), 0 0 8px rgba(223, 186, 82, 0.55) !important;
}

/* 2.1.5 CSS 降级回退层：在 JS 未注入前先行呈现玫瑰花与顶部尖尖光标 */
:is([data-testid="conversation-row-sidebar"], .agy-sidebar-row):is([data-selected="true"], [data-active="true"], [aria-selected="true"]):not(button[data-testid="project-header"]):not(button[data-project-card="true"]):not([data-project-label]):not(:has(.pm-cursor-layer))::before {
  content: '' !important;
  position: absolute !important;
  top: -19px !important;
  right: 62px !important; /* 精准对齐上方内侧十字缎带 */
  width: 25px !important;
  height: 25px !important;
  background-image: url("data:image/webp;base64,") !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-size: contain !important;
  filter: drop-shadow(0 2px 6px rgba(0, 0, 0, 0.9)) drop-shadow(0 0 6px rgba(223, 186, 82, 0.35)) !important;
  pointer-events: none !important;
  z-index: 25 !important;
  will-change: transform, opacity !important;
  animation: pm-rose-breathe 2.8s ease-in-out infinite alternate !important;
}

:is([data-testid="conversation-row-sidebar"], .agy-sidebar-row):is([data-selected="true"], [data-active="true"], [aria-selected="true"]):not(button[data-testid="project-header"]):not(button[data-project-card="true"]):not([data-project-label]):not(:has(.pm-cursor-layer))::after {
  content: '' !important;
  position: absolute !important;
  top: -24px !important;
  right: 8px !important; /* 精准对齐最右侧十字尖端 */
  width: 14px !important;
  height: 34px !important;
  background-image: url("data:image/webp;base64,") !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-size: contain !important;
  filter: drop-shadow(0 2px 5px rgba(0, 0, 0, 0.85)) drop-shadow(0 0 8px rgba(223, 186, 82, 0.5)) !important;
  pointer-events: none !important;
  z-index: 25 !important;
  animation: pm-needle-wave-top 1.8s ease-in-out infinite alternate !important;
}

/* 2.1.6 选中项专属法器图层：唯有选中项才挂载的顶部玫瑰花与上下浮动尖尖光标 (DOM 独立节点) */
.pm-cursor-layer {
  position: absolute !important;
  inset: 0 !important;
  pointer-events: none !important;
  z-index: 30 !important;
  overflow: visible !important;
}

/* (1) 仅在选中项出现的顶部绯红玫瑰花 (SL_Rose) */
.pm-rose-crown {
  position: absolute !important;
  top: -19px !important;
  right: 62px !important; /* 精准对齐上方内侧十字缎带 */
  width: 25px !important;
  height: 25px !important;
  background-image: url("data:image/webp;base64,") !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-size: contain !important;
  filter: drop-shadow(0 2px 6px rgba(0, 0, 0, 0.9)) drop-shadow(0 0 7px rgba(223, 186, 82, 0.4)) !important;
  will-change: transform, opacity !important;
  animation: pm-rose-breathe 2.8s ease-in-out infinite alternate !important;
}

@keyframes pm-rose-breathe {
  0% {
    transform: translateY(0) scale(0.96);
    opacity: 0.88;
  }
  100% {
    transform: translateY(-2px) scale(1.04);
    opacity: 1;
  }
}

/* (2) 上方金色尖尖光标：指向右端十字花，上下浮动 */
.pm-needle-top {
  position: absolute !important;
  top: -24px !important;
  right: 8px !important; /* 精准对齐最右侧十字尖端 */
  width: 14px !important;
  height: 34px !important;
  background-image: url("data:image/webp;base64,") !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-size: contain !important;
  filter: drop-shadow(0 2px 5px rgba(0, 0, 0, 0.85)) drop-shadow(0 0 8px rgba(223, 186, 82, 0.5)) !important;
  animation: pm-needle-wave-top 1.8s ease-in-out infinite alternate !important;
}

/* (3) 下方金色尖尖光标：倒转指向右端十字花，反相上下浮动 */
.pm-needle-bottom {
  position: absolute !important;
  bottom: -24px !important;
  right: 8px !important; /* 精准对齐最右侧十字尖端 */
  width: 14px !important;
  height: 34px !important;
  background-image: url("data:image/webp;base64,") !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-size: contain !important;
  filter: drop-shadow(0 2px 5px rgba(0, 0, 0, 0.85)) drop-shadow(0 0 8px rgba(223, 186, 82, 0.5)) !important;
  animation: pm-needle-wave-bottom 1.8s ease-in-out infinite alternate !important;
}

@keyframes pm-needle-wave-top {
  0% {
    transform: translateY(0);
  }
  100% {
    transform: translateY(5px);
  }
}

@keyframes pm-needle-wave-bottom {
  0% {
    transform: translateY(0);
  }
  100% {
    transform: translateY(-5px);
  }
}

/* 2.1.7 文件夹及项目头部容器彻底排除 SL_Box 背景，保持原生整洁折叠栏 */
button[data-testid="project-header"],
button[data-project-card="true"],
[data-project-label],
.bg-sidebar [data-testid="project-header"],
.bg-sidebar [data-project-card="true"] {
  background-image: none !important;
  background-color: transparent !important;
  transform: none !important;
  filter: none !important;
  opacity: 1 !important;
  box-shadow: none !important;
  min-height: unset !important;
  height: unset !important;
}


/* ----------------------------------------------------------------------------
 * 2.2 《Pocket Mirror》右侧副栏/工具视窗：毛玻璃半透明高斯模糊与主菜单华丽拱门
 *     - 常态窄栏：半透明暗曜底色 + 高斯模糊 (backdrop-filter: blur(20px))，
 *       内部快捷菜单套用 promptWindowBorder.png 原作相框；
 *     - 完全展开：自适应切换为 MM_FrameUp.png 皇家金拱门 + MM_FrameDown.png 玫瑰蔓藤底阑
 *       + MM_MenuGradient.png 渐变心格地毯。
 * ---------------------------------------------------------------------------- */

/* 2.2.1 右侧边栏与工具窗体：华丽维多利亚客室全景联动（方案1：视口一体化联动） */
[data-side-panel-body],
.agy-inset-shell [data-side-panel-body] {
  container-type: inline-size !important;
  background-color: #0d090a !important;
  background-image: url("data:image/webp;base64,") !important;
  background-attachment: fixed !important;
  background-position: left top !important;
  background-size: cover !important;
  background-repeat: no-repeat !important;
  border-left: 1.5px solid rgba(212, 175, 55, 0.4) !important;
  box-shadow: inset 1px 0 24px rgba(0, 0, 0, 0.75), -4px 0 20px rgba(0, 0, 0, 0.5) !important;
  transition: background 0.35s ease, backdrop-filter 0.35s ease !important;
}

/* 内部嵌套容器透明化，让全景客室背景透出 */
[data-side-panel-focus-scope],
[data-testid="side-panel-new-tab-view"],
div:has(> [data-testid="side-panel-new-tab-view"]) {
  background: transparent !important;
  background-image: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: none !important;
  box-shadow: none !important;
}

/* 顶部标签条透光沉浸 (承袭父级毛玻璃，无须重复模糊) */
[data-side-panel-strip] {
  background-color: rgba(16, 6, 14, 0.85) !important;
  border-bottom: 1px solid rgba(212, 175, 55, 0.3) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* 2.2.2 搜索栏：暗夜石英底色与微光细金边 */
[data-testid="new-tab-search-input"],
input[placeholder*="搜索或输入网址"],
input[data-ag-orig-placeholder*="Search"] {
  background-color: rgba(28, 9, 20, 0.78) !important;
  border: 1.5px solid rgba(212, 175, 55, 0.45) !important;
  border-radius: 10px !important;
  color: #f7f1e5 !important;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.6), inset 0 1px 3px rgba(0, 0, 0, 0.5) !important;
  font-family: 'Lora', 'Source Han Serif SC', serif !important;
  font-size: 13.5px !important;
}

/* 2.2.3 常态窄栏状态：文本菜单列表套用 promptWindowBorder.png 哥特相框 */
[data-side-panel-body] [data-testid="side-panel-new-tab-view"] div.flex-col:has(> button[data-testid^="new-tab-card"]),
[data-side-panel-body] div.flex-col:has(> button[data-testid^="new-tab-card"]) {
  position: relative !important;
  background-image: url("data:image/webp;base64,") !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-size: 100% 100% !important;
  background-color: rgba(22, 7, 16, 0.88) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  padding: 44px 22px 32px 22px !important;
  border-radius: 14px !important;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.8), 0 0 12px rgba(223, 186, 82, 0.25) !important;
  border: 1px solid rgba(212, 175, 55, 0.25) !important;
  margin-top: 10px !important;
}

/* 列表文本项衬线排版与掠过高光 */
[data-side-panel-body] button[data-testid^="new-tab-card"] {
  font-family: 'Lora', 'Source Han Serif SC', serif !important;
  font-size: 14px !important;
  color: #ede2d3 !important;
  padding: 7px 12px !important;
  border-radius: 8px !important;
  transition: background-color 0.2s ease, transform 0.2s ease, color 0.2s ease !important;
