/* ============================================================================
 * 🎭 《Pocket Mirror: Goldenertraum》恶魔马戏团舞台帷幕 (实时可调参版 v12)
 * ============================================================================ */

:root {
  --curtain-close-dur: 0.36s;
  --curtain-open-dur: 0.36s;
  --curtain-easing: cubic-bezier(0.2, 0.85, 0.3, 1);
}

/* 1. 常驻全屏边缘大剧场帷幕画框 */
#antigravity-curtain-overlay {
  position: fixed !important;
  inset: 0 !important;
  width: 100vw !important;
  height: 100vh !important;
  pointer-events: none !important;
  z-index: 99980 !important;
  background-image: url("data:image/webp;base64,") !important;
  background-size: 100% 100% !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  
  transform: translate3d(0, 0, 0) !important;
  backface-visibility: hidden !important;
  contain: strict !important;
  will-change: opacity !important;
  
  opacity: 0.96;
  transition: opacity 0.22s cubic-bezier(0.25, 1, 0.5, 1) !important;
}

#antigravity-curtain-overlay.hover-sidebar {
  opacity: 0.12 !important;
}

#antigravity-curtain-overlay.hover-right {
  opacity: 0.25 !important;
}

/* 2. 核心：双向关键帧 */
@keyframes agy-curtain-close-left {
  0% { transform: translate3d(-50%, 0, 0); }
  100% { transform: translate3d(0, 0, 0); }
}

@keyframes agy-curtain-close-right {
  0% { transform: translate3d(50%, 0, 0); }
  100% { transform: translate3d(0, 0, 0); }
}

@keyframes agy-curtain-open-left {
  0% { transform: translate3d(0, 0, 0); }
  100% { transform: translate3d(-50%, 0, 0); }
}

@keyframes agy-curtain-open-right {
  0% { transform: translate3d(0, 0, 0); }
  100% { transform: translate3d(50%, 0, 0); }
}

/* 3. 转场大拉幕容器 */
#antigravity-curtain-transition {
  position: fixed !important;
  inset: 0 !important;
  width: 100vw !important;
  height: 100vh !important;
  pointer-events: none !important;
  z-index: 99998 !important;
  overflow: hidden !important;
  
  visibility: hidden !important;
  opacity: 0 !important;
  transition: opacity 0.1s ease !important;
  contain: strict !important;
}

#antigravity-curtain-transition.active {
  visibility: visible !important;
  opacity: 1 !important;
}

#antigravity-curtain-transition .agy-curtain-half-left {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  background-image: url("data:image/webp;base64,") !important;
  background-size: 100% 100% !important;
  background-repeat: no-repeat !important;
  transform: translate3d(-50%, 0, 0);
  will-change: transform !important;
  backface-visibility: hidden !important;
}

#antigravity-curtain-transition .agy-curtain-half-right {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  background-image: url("data:image/webp;base64,") !important;
  background-size: 100% 100% !important;
  background-repeat: no-repeat !important;
  transform: translate3d(50%, 0, 0);
  will-change: transform !important;
  backface-visibility: hidden !important;
}

/* 闭幕动画：时长绑定 CSS 变量 --curtain-close-dur */
#antigravity-curtain-transition.closing .agy-curtain-half-left {
  animation: agy-curtain-close-left var(--curtain-close-dur, 0.36s) var(--curtain-easing, cubic-bezier(0.2, 0.85, 0.3, 1)) forwards !important;
}
#antigravity-curtain-transition.closing .agy-curtain-half-right {
  animation: agy-curtain-close-right var(--curtain-close-dur, 0.36s) var(--curtain-easing, cubic-bezier(0.2, 0.85, 0.3, 1)) forwards !important;
}

#antigravity-curtain-transition.closed-hold .agy-curtain-half-left,
#antigravity-curtain-transition.closed-hold .agy-curtain-half-right {
  animation: none !important;
  transform: translate3d(0, 0, 0) !important;
}

/* 开幕动画：时长绑定 CSS 变量 --curtain-open-dur */
#antigravity-curtain-transition.opening .agy-curtain-half-left {
  animation: agy-curtain-open-left var(--curtain-open-dur, 0.36s) var(--curtain-easing, cubic-bezier(0.2, 0.85, 0.3, 1)) forwards !important;
}
#antigravity-curtain-transition.opening .agy-curtain-half-right {
  animation: agy-curtain-open-right var(--curtain-open-dur, 0.36s) var(--curtain-easing, cubic-bezier(0.2, 0.85, 0.3, 1)) forwards !important;
}

#antigravity-curtain-transition .agy-curtain-frame {
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  background-image: url("data:image/webp;base64,") !important;
  background-size: 100% 100% !important;
  background-repeat: no-repeat !important;
  pointer-events: none !important;
}

