/* 1. 禁用 IDE 原生缩放，确保纯净平移质感 */
.settings-modal-container.animate-modalScaleIn {
  animation: none !important;
}

/* 2. 幕布：仅对背景与高斯模糊做平滑渐变，不改变父级 opacity 避免误伤容器内子组件 */
@keyframes pmBackdropFadeIn {
  0% {
    backdrop-filter: blur(0px);
    background-color: rgba(0, 0, 0, 0);
  }
  100% {
    backdrop-filter: blur(12px);
    background-color: rgba(0, 0, 0, 0.45);
  }
}

@keyframes pmBackdropFadeOut {
  0% {
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}

.settings-modal-backdrop:not([data-modal-closing="true"]) {
  animation: pmBackdropFadeIn 0.38s ease-out both !important;
}

.settings-modal-backdrop[data-modal-closing="true"],
.settings-modal-backdrop[data-ending-style],
.settings-modal-backdrop[data-closed],
.settings-modal-backdrop.animate-modalFadeOut {
  animation: pmBackdropFastFade 0.15s ease-out both !important;
  backdrop-filter: none !important;
  will-change: opacity !important;
  pointer-events: none !important;
}

@keyframes pmBackdropFastFade {
  0% { opacity: 1; }
  100% { opacity: 0; }
}

/* 3. 容器：无外边框 + 径向深红丝绒渐变背景 + 溢出隐藏 */
.settings-modal-container {
  overflow: hidden !important;
  opacity: 1 !important;
  border: none !important;
  box-shadow: none !important;
  background: radial-gradient(ellipse 640px 360px at center, rgba(35, 10, 24, 0.95) 0%, rgba(20, 5, 14, 0.92) 55%, rgba(12, 3, 8, 0.6) 80%, rgba(0, 0, 0, 0) 100%) !important;
}

