/* 当处于二级详情激活状态（非关闭中）时，触发从底部升起 */
.settings-modal-container[data-active-detail="true"]:not([data-scene-transition="closing"]):not([data-modal-closing="true"]) #pm-options-frame,
.settings-modal-container[data-active-detail="true"]:not([data-scene-transition="closing"]):not([data-modal-closing="true"]) [data-testid="settings-sidebar"],
.settings-modal-container[data-active-detail="true"]:not([data-scene-transition="closing"]):not([data-modal-closing="true"]) .w-full.bg-transparent.h-full.overflow-y-auto,
.settings-modal-container[data-active-detail="true"]:not([data-scene-transition="closing"]):not([data-modal-closing="true"]) #pm-return-btn,
.settings-modal-container[data-active-detail="true"]:not([data-scene-transition="closing"]):not([data-modal-closing="true"]) #pm-key-hints {
  animation: pmSettingsSlideUp 0.45s cubic-bezier(0, 0, 0.25, 1) both !important;
}

/* 当处于返回一级菜单（scene closing）或全局退出（modal closing）时，触发向底部沉降 */
.settings-modal-container[data-scene-transition="closing"] #pm-options-frame,
.settings-modal-container[data-scene-transition="closing"] [data-testid="settings-sidebar"],
.settings-modal-container[data-scene-transition="closing"] .w-full.bg-transparent.h-full.overflow-y-auto,
.settings-modal-container[data-scene-transition="closing"] #pm-return-btn,
.settings-modal-container[data-scene-transition="closing"] #pm-key-hints,
.settings-modal-container[data-active-detail="true"][data-modal-closing="true"] #pm-options-frame,
.settings-modal-container[data-active-detail="true"][data-modal-closing="true"] [data-testid="settings-sidebar"],
.settings-modal-container[data-active-detail="true"][data-modal-closing="true"] .w-full.bg-transparent.h-full.overflow-y-auto,
.settings-modal-container[data-active-detail="true"][data-modal-closing="true"] #pm-return-btn,
.settings-modal-container[data-active-detail="true"][data-modal-closing="true"] #pm-key-hints {
  animation: pmSettingsSlideDown 0.12s cubic-bezier(0.2, 0, 0, 1) both !important;
}


/* ============================================================================
 * 《Pocket Mirror》设置界面 - 语言切换卡片与 HUD 快捷切换样式
 * ============================================================================ */
.pm-language-card {
  position: relative !important;
  width: 100% !important;
  box-sizing: border-box !important;
  padding: 16px 20px !important;
  margin-bottom: 8px !important;
  background: rgba(26, 11, 22, 0.92) !important;
  border: 1.5px solid rgba(212, 175, 55, 0.5) !important;
  border-radius: 4px !important;
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.7), inset 0 0 12px rgba(212, 175, 55, 0.08) !important;
  backdrop-filter: blur(8px) !important;
}

.pm-language-card:hover {
  border-color: rgba(212, 175, 55, 0.75) !important;
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.8), inset 0 0 16px rgba(212, 175, 55, 0.15) !important;
}

.pm-card-title-group {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
}

.pm-card-title-icon {
  font-size: 18px !important;
}

.pm-card-title {
  font-family: 'Cinzel', 'Noto Serif SC', serif !important;
  font-size: 16px !important;
  font-weight: 600 !important;
  color: #ffd700 !important;
  text-shadow: 0 0 8px rgba(212, 175, 55, 0.5) !important;
  letter-spacing: 0.5px !important;
}

.pm-card-desc {
  font-size: 12px !important;
  color: #c4a872 !important;
  margin-top: 4px !important;
  line-height: 1.4 !important;
}

.pm-lang-toggle-group {
  display: flex !important;
  gap: 12px !important;
  margin-top: 14px !important;
}

.pm-lang-btn {
  flex: 1 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  padding: 10px 16px !important;
  background: rgba(45, 18, 36, 0.7) !important;
  border: 1px solid rgba(138, 109, 59, 0.5) !important;
  border-radius: 4px !important;
  color: #e0d8cc !important;
  cursor: pointer !important;
  transition: all 0.22s cubic-bezier(0.16, 1, 0.3, 1) !important;
  outline: none !important;
}

.pm-lang-btn:hover {
  background: rgba(65, 26, 52, 0.85) !important;
  border-color: #d4af37 !important;
  box-shadow: 0 0 12px rgba(212, 175, 55, 0.3) !important;
  transform: translateY(-1px) !important;
}

.pm-lang-btn.active {
  background: linear-gradient(135deg, rgba(80, 28, 56, 0.95), rgba(50, 16, 36, 0.95)) !important;
  border: 1.5px solid #ffd700 !important;
  color: #ffffff !important;
  box-shadow: 0 0 16px rgba(212, 175, 55, 0.45), inset 0 0 10px rgba(212, 175, 55, 0.2) !important;
}

.pm-lang-btn-left {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
}

.pm-lang-btn-icon {
  font-size: 16px !important;
}

.pm-lang-btn-label {
  font-family: 'Cinzel', 'Noto Serif SC', serif !important;
  font-size: 14px !important;
  font-weight: 500 !important;
}

.pm-lang-badge {
  font-size: 11px !important;
  padding: 2px 8px !important;
  border-radius: 10px !important;
  background: rgba(0, 0, 0, 0.4) !important;
  border: 1px solid rgba(212, 175, 55, 0.3) !important;
  color: #c4a872 !important;
  transition: all 0.2s ease !important;
}

.pm-lang-btn.active .pm-lang-badge {
  background: rgba(212, 175, 55, 0.25) !important;
  border-color: #ffd700 !important;
  color: #ffd700 !important;
  box-shadow: 0 0 8px rgba(212, 175, 55, 0.3) !important;
}

/* HUD 快捷语言切换按键 */
.pm-quick-lang-btn {
  background: rgba(45, 18, 36, 0.75) !important;
  border: 1px solid rgba(138, 109, 59, 0.5) !important;
  border-radius: 3px !important;
  color: #c4a872 !important;
  font-family: 'Cinzel', 'Noto Serif SC', serif !important;
  font-size: 11px !important;
  padding: 2px 8px !important;
  cursor: pointer !important;
  transition: all 0.2s ease !important;
}

.pm-quick-lang-btn:hover {
  background: rgba(70, 28, 56, 0.9) !important;
  border-color: #ffd700 !important;
  color: #ffffff !important;
}

.pm-quick-lang-btn.active {
  background: rgba(90, 32, 64, 0.95) !important;
  border: 1px solid #ffd700 !important;
  color: #ffd700 !important;
  box-shadow: 0 0 8px rgba(212, 175, 55, 0.4) !important;
  font-weight: bold !important;
}


/* ============================================================================
 * 🌹 首页问候语上方 Antigravity 水印 Logo 升级为专属华丽金玫瑰版
 * ============================================================================ */
.home-greeting-mark,
.dark .home-greeting-mark {
  display: block !important;
  opacity: 0.95 !important;
  -webkit-mask-image: none !important;
  mask-image: none !important;
  width: 140px !important;
  height: 140px !important;
  background-image: url("data:image/png;base64,") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  filter: drop-shadow(0 4px 20px rgba(212, 175, 55, 0.45)) drop-shadow(0 0 8px rgba(255, 230, 150, 0.3)) !important;
  transition: all 0.3s cubic-bezier(0.2, 0.85, 0.3, 1) !important;
  margin-bottom: 12px !important;
}

.home-greeting-mark:hover {
  transform: scale(1.05) translateY(-2px) !important;
  filter: drop-shadow(0 6px 28px rgba(212, 175, 55, 0.7)) drop-shadow(0 0 14px rgba(255, 240, 180, 0.5)) !important;
}

.home-greeting-mark path {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
}
